fn solve(n: i8, k: i8) -> Vec<i8> {
    // If no items are selected or all items are selected,
    // there can be no "good" unselected items.
    if k == 0 || k == n {
        return vec![0, 0];
    }

    // Otherwise, the minimum is 1, and the maximum is the lesser of
    // (unselected items) and (twice the selected items).
    let unselected = n - k;
    let x_max = unselected.min(2 * k);

    vec![1, x_max]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_solve() {
        // Edge cases: k == 0 or k == n
        assert_eq!(solve(5, 0), vec![0, 0]);
        assert_eq!(solve(5, 5), vec![0, 0]);
        assert_eq!(solve(1, 0), vec![0, 0]);
        assert_eq!(solve(1, 1), vec![0, 0]);

        // General cases
        assert_eq!(solve(5, 1), vec![1, 2]); // unselected = 4, 2*k = 2 -> max = 2
        assert_eq!(solve(5, 2), vec![1, 3]); // unselected = 3, 2*k = 4 -> max = 3
        assert_eq!(solve(5, 3), vec![1, 2]); // unselected = 2, 2*k = 6 -> max = 2
        assert_eq!(solve(10, 4), vec![1, 8.min(10 - 4)]); // max = min(6, 8) = 6
    }
}